            const m = $('.view button[data-m="m"]');
            if (!(await aim(m, 0.5, 0.5))) return;
            await tap(m, () => m.click());
            await wait(2800);
            const d = $('.view button[data-m="d"]');
            if (!(await aim(d, 0.5, 0.5))) return;
            await tap(d, () => d.click());
            await wait(1100);
