          return `M${p[0]},${p[1]} C${p[0] + (r ? k : -k)},${p[1]} ${q[0] + (r ? -k : k)},${q[1]} ${q[0]},${q[1]}`;
        }
        const d = dy > 0;
        const p = [ax + aw / 2, d ? ay + ah : ay];
        const q = [bx + bw / 2, d ? by : by + bh];
        const k = Math.abs(q[1] - p[1]) / 2;
        return `M${p[0]},${p[1]} C${p[0]},${p[1] + (d ? k : -k)} ${q[0]},${q[1] + (d ? -k : k)} ${q[0]},${q[1]}`;
