          }
          await wait(5200);
        }
      })();

      const IDEAS = ['Check fuel costs per lane', 'Ask Hana about depot hours', 'Test night routes in Porto'];
      let ti = 0;
      cur.style.transform = 'translate(700px,500px)';
      (async () => {
        await wait(1800);
