          }
          const flow = async () => {
            const tb = $('.tool[data-t="sticky"]');
            if (!(await aim(tb, 0.5, 0.5))) return;
            await tap(tb, () => tb.click());
            await wait(200);
            if (!(await aim(plane, 0.72, 0.64))) return;
